-- Save MJ: Queries (core SP call only)
DO $mj$
DECLARE
  p_Name_72a06f7b9134 VARCHAR(255);
  p_CategoryID_72a06f7b9134 UUID;
  p_UserQuestion_72a06f7b9134 TEXT;
  p_Description_72a06f7b9134 TEXT;
  p_SQL_72a06f7b9134 TEXT;
  p_TechnicalDescription_72a06f7b9134 TEXT;
  p_OriginalSQL_72a06f7b9134 TEXT;
  p_Feedback_72a06f7b9134 TEXT;
  p_Status_72a06f7b9134 VARCHAR(15);
  p_QualityRank_72a06f7b9134 INTEGER;
  p_ExecutionCostRank_72a06f7b9134 INTEGER;
  p_UsesTemplate_72a06f7b9134 BOOLEAN;
  p_AuditQueryRuns_72a06f7b9134 BOOLEAN;
  p_CacheEnabled_72a06f7b9134 BOOLEAN;
  p_CacheTTLMinutes_72a06f7b9134 INTEGER;
  p_CacheMaxSize_72a06f7b9134 INTEGER;
  p_EmbeddingVector_72a06f7b9134 TEXT;
  p_EmbeddingModelID_72a06f7b9134 UUID;
  p_CacheValidationSQL_72a06f7b9134 TEXT;
  p_SQLDialectID_72a06f7b9134 UUID;
  p_Reusable_72a06f7b9134 BOOLEAN;
  p_ExternalDataSourceID_72a06f7b9134 UUID;
  p_IsMaterialized_72a06f7b9134 BOOLEAN;
  p_ID_72a06f7b9134 UUID;
BEGIN
  p_Name_72a06f7b9134 := 'Party Order Lifetime';
  p_CategoryID_72a06f7b9134 := 'D6586F51-1F67-4F50-BA28-7DB8A98BD4D2';
  p_UserQuestion_72a06f7b9134 := 'What is this person or organization''s order lifetime — counts, LTV, and years as a customer?';
  p_Description_72a06f7b9134 := 'Single-row party header stats: non-voided order count, open/overdue counts, lifetime gross, first order date, years as customer, and active subscription count. Used by the Person and Organization form headers so those figures are one indexed aggregate instead of four count RunViews plus extra money queries.';
  p_SQL_72a06f7b9134 := '-- One-row party lifetime for the Person / Organization form header.
-- PartyKind is only used in Nunjucks branches — it never touches SQL text.
-- PartyID is quoted via sqlString.
-- Years are counted to the BUSINESS day (fnBusinessToday), not the UTC one, which turns the year
-- over on Dec 31 evening for anyone west of Greenwich.
SELECT
    ISNULL(o.OrderCount, 0) AS OrderCount,
    ISNULL(o.OpenCount, 0) AS OpenCount,
    ISNULL(o.OverdueCount, 0) AS OverdueCount,
    ISNULL(o.LifetimeValue, 0) AS LifetimeValue,
    o.FirstOrderDate,
    CASE
        WHEN o.FirstOrderDate IS NULL THEN NULL
        ELSE DATEDIFF(year, o.FirstOrderDate, bt.Today)
    END AS YearsAsCustomer,
    ISNULL(s.ActiveSubCount, 0) AS ActiveSubCount
FROM (SELECT 1 AS OneRow) AS seed
CROSS JOIN [__mj_BizAppsCommon].[fnBusinessToday]() AS bt
OUTER APPLY (
    SELECT
        COUNT(*) AS OrderCount,
        SUM(CASE WHEN ISNULL(h.IsOverdue, 0) = 1 OR ISNULL(h.Balance, 0) > 0 THEN 1 ELSE 0 END) AS OpenCount,
        SUM(CASE WHEN ISNULL(h.IsOverdue, 0) = 1 THEN 1 ELSE 0 END) AS OverdueCount,
        SUM(ISNULL(h.TotalGross, 0)) AS LifetimeValue,
        MIN(h.OrderDate) AS FirstOrderDate
    FROM [__mj_BizAppsOrders].vwOrderHeaders h
    WHERE h.Status <> N''Voided''
      {% if PartyKind == "person" %}
      AND h.BillToPersonID = {{ PartyID | sqlString }}
      {% else %}
      AND h.BillToOrganizationID = {{ PartyID | sqlString }}
      {% endif %}
) o
OUTER APPLY (
    SELECT COUNT(*) AS ActiveSubCount
    FROM [__mj_BizAppsOrders].vwSubscriptions sub
    WHERE sub.Status = N''Active''
      {% if PartyKind == "person" %}
      AND sub.BeneficiaryPersonID = {{ PartyID | sqlString }}
      {% else %}
      AND sub.HolderOrganizationID = {{ PartyID | sqlString }}
      {% endif %}
) s;
';
  p_TechnicalDescription_72a06f7b9134 := 'Nunjucks-parameterized. PartyKind (person|organization) selects the bill-to / subscription join column; PartyID is the party UUID and is always passed through the sqlString filter. Aggregates __mj_BizAppsOrders.vwOrderHeaders (Status <> Voided) and vwSubscriptions (Status = Active). Returns one row even when the party has no orders.';
  p_Status_72a06f7b9134 := 'Approved';
  p_QualityRank_72a06f7b9134 := 8;
  p_ExecutionCostRank_72a06f7b9134 := 2;
  p_UsesTemplate_72a06f7b9134 := TRUE;
  p_AuditQueryRuns_72a06f7b9134 := FALSE;
  p_CacheEnabled_72a06f7b9134 := FALSE;
