  p_ID_72a06f7b9134 := COALESCE((SELECT "ID" FROM "${mjSchema}"."Query" WHERE "Name" = 'Party Order Lifetime' ORDER BY CASE WHEN "ID" = p_ID_72a06f7b9134 THEN 0 ELSE 1 END LIMIT 1), p_ID_72a06f7b9134);
  p_CategoryID_72a06f7b9134 := COALESCE((SELECT "ID" FROM "${mjSchema}"."QueryCategory" WHERE "Name" = 'Orders' ORDER BY CASE WHEN "ID" = p_CategoryID_72a06f7b9134 THEN 0 ELSE 1 END LIMIT 1), p_CategoryID_72a06f7b9134);
  IF EXISTS (
