-- Save MJ: Authorizations (core SP call only)
DO $mj$
DECLARE
  p_ParentID_c45a5ea4f2a5 UUID;
  p_Name_c45a5ea4f2a5 VARCHAR(100);
  p_IsActive_c45a5ea4f2a5 BOOLEAN;
  p_UseAuditLog_c45a5ea4f2a5 BOOLEAN;
  p_Description_c45a5ea4f2a5 TEXT;
  p_ID_c45a5ea4f2a5 UUID;
BEGIN
  p_Name_c45a5ea4f2a5 := 'MJ.BizApps.Orders.Access.Override';
  p_IsActive_c45a5ea4f2a5 := TRUE;
  p_UseAuditLog_c45a5ea4f2a5 := TRUE;
  p_Description_c45a5ea4f2a5 := 'Parent grant for requesting exceptions to payment-gated access on an order. Child authorizations are WaivePaymentHold and DeferCutoff, one per override type. Holding the parent grants both. A request is approved by the order company''s ApprovalCFOUserID, or by the AccessOverrideFallbackApproverRole when that user requested it (bizapps-orders#360).';
  p_ID_c45a5ea4f2a5 := 'AB81C474-1942-40C9-A05F-90E441C7A7F7';
  p_ID_c45a5ea4f2a5 := COALESCE((SELECT "ID" FROM "${mjSchema}"."Authorization" WHERE "Name" = 'MJ.BizApps.Orders.Access.Override' ORDER BY CASE WHEN "ID" = p_ID_c45a5ea4f2a5 THEN 0 ELSE 1 END LIMIT 1), p_ID_c45a5ea4f2a5);
  IF EXISTS (
    SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = '${mjSchema}' AND p.proname = 'spUpdateAuthorization'
       AND p.pronargs = 1 AND p.proargtypes[0] = 'jsonb'::regtype
  ) THEN
    PERFORM "${mjSchema}"."spUpdateAuthorization"(p_data := jsonb_build_object(
    'ParentID', p_ParentID_c45a5ea4f2a5,
    'Name', p_Name_c45a5ea4f2a5,
    'IsActive', p_IsActive_c45a5ea4f2a5,
    'UseAuditLog', p_UseAuditLog_c45a5ea4f2a5,
    'Description', p_Description_c45a5ea4f2a5,
    'ID', p_ID_c45a5ea4f2a5
  ));
  ELSE
    PERFORM "${mjSchema}"."spUpdateAuthorization"(p_ParentID := p_ParentID_c45a5ea4f2a5, p_ParentID_Clear := TRUE, p_Name := p_Name_c45a5ea4f2a5, p_IsActive := p_IsActive_c45a5ea4f2a5, p_UseAuditLog := p_UseAuditLog_c45a5ea4f2a5, p_Description := p_Description_c45a5ea4f2a5, p_ID := p_ID_c45a5ea4f2a5);
  END IF;
END $mj$;

